import{categories,validPlan,simulate,migratePlan}from'./calculation.js';const $=id=>document.getElementById(id);const key='yapps.investment-simulator.v1';const noticeKey='yapps.investment-simulator.storage-notice-dismissed';try{$('storage-notice').hidden=localStorage.getItem(noticeKey)==='true';}catch{}
$('dismiss-storage-notice').addEventListener('click',()=>{$('storage-notice').hidden=true;try{localStorage.setItem(noticeKey,'true');}catch{}});const colors=['#248879','#5895d3','#daa342','#a57bc0','#d37e75','#637daa','#86a64f'];const color=i=>colors[i]||`hsl(${(i*137.5)%360}48%48%)`;const yen=n=>`${Math.round(n).toLocaleString('ja-JP')}円`;const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let plan={years:20,products:[{name:'国内株ファンド',category:'国内株',initial:0,monthly:10000,rate:3},{name:'アメリカ株ファンド',category:'アメリカ株',initial:0,monthly:20000,rate:5},{name:'金ファンド',category:'金',initial:0,monthly:5000,rate:2},]};try{const saved=localStorage.getItem(key);if(saved){const parsed=migratePlan(JSON.parse(saved));if(!validPlan(parsed))throw new Error('Invalid data');plan=parsed;$('save-status').textContent='保存済みのプランを復元しました';}else $('save-status').textContent='変更すると、このブラウザに自動保存';}catch{$('save-status').textContent='保存内容を読み込めないため、操作例を表示しています';}
function renderProducts(){$('years').value=plan.years;$('products').innerHTML=plan.products.map((p,i)=>`<div class="product"style="--product-color:${color(i)}"><label>商品名<input data-field="name"maxlength="80"value="${escape(p.name)}"aria-label="商品${i + 1}の商品名"></label><label>カテゴリ<select data-field="category"aria-label="商品${i + 1}のカテゴリ">${categories.map(c=>`<option${c===p.category?' selected':''}>${c}</option>`).join('')}</select></label><label>初期投資額（円）<input data-field="initial"type="number"min="0"max="1000000000"step="1"required value="${p.initial}"></label><label>毎月の積立額（円）<input data-field="monthly"type="number"min="0"max="1000000000"step="1"required value="${p.monthly}"></label><label>年利（%）<input data-field="rate"type="number"min="-100"max="100"step="any"required value="${p.rate}"></label><button type="button"data-remove="${i}"aria-label="商品${i + 1}を削除"${plan.products.length===1?'disabled':''}>削除</button></div>`).join('');$('add-product').disabled=plan.products.length>=30;}
function readPlan(){return{years:Number($('years').value),products:[...$('products').children].map(row=>Object.fromEntries([...row.querySelectorAll('[data-field]')].map(input=>[input.dataset.field,['name','category'].includes(input.dataset.field)?input.value:Number(input.value)])))};}
function update(save=true){const next=readPlan();const valid=$('plan').checkValidity()&&validPlan(next);$('error').textContent=valid?'':'運用期間は1〜60年、金額は0〜10億円の整数、年利は−100〜100%で入力してください。空欄の数値も入力してください。';$('results').hidden=!valid;if(!valid)return false;plan=next;if(save){try{localStorage.setItem(key,JSON.stringify(plan));$('save-status').textContent='✓ このブラウザに保存済み';}
catch{$('save-status').textContent='保存できませんでした。計算は引き続き利用できます。';}}
renderResults(simulate(plan));return true;}
function legend(items,target,withAmounts=false){const total=items.reduce((sum,item)=>sum+(item.value||0),0);$(target).innerHTML=items.map(item=>`<span class="legend-item"><span class="swatch"style="background:${item.color}"></span>${escape(item.name)}${withAmounts?`：${yen(item.value)}（${total?(item.value/total*100).toFixed(1):'0.0'}%）`:''}</span>`).join('');}
function renderResults(result){$('final-label').textContent=`${plan.years}年後の評価額`;$('total').textContent=yen(result.final.total);$('principal').textContent=yen(result.final.principal);$('gain').textContent=`${result.final.total>=result.final.principal?'+':''}${yen(result.final.total-result.final.principal)}`;$('monthly').textContent=yen(result.monthly);const items=plan.products.map((p,i)=>({name:p.name.trim()||`商品${i+1}`,color:color(i)}));const rows=result.rows;const max=Math.max(1,...rows.map(r=>Math.max(r.total,r.principal)))*1.1;const x=year=>75+year/plan.years*600;const y=value=>285-value/max*250;const layers=rows.map(()=>0);let paths='';items.forEach((item,i)=>{const bottom=[...layers];rows.forEach((row,j)=>{layers[j]+=row.balances[i];});const points=rows.map((row,j)=>`${x(row.year)},${y(layers[j])}`).concat(rows.map((row,j)=>`${x(row.year)},${y(bottom[j])}`).reverse());paths+=`<path d="M${points.join(' L')} Z"fill="${item.color}"fill-opacity=".85"><title>${escape(item.name)}：${yen(result.final.balances[i])}</title></path>`;});let axes='';for(let i=0;i<=4;i++){const value=max*i/4;const label=value>=1e8?`${(value/1e8).toFixed(1)}億`:value>=1e4?`${(value/1e4).toFixed(0)}万`:Math.round(value);axes+=`<line x1="75"x2="675"y1="${y(value)}"y2="${y(value)}"stroke="#e4ebe7"/><text x="65"y="${y(value) + 4}"text-anchor="end">${label}</text>`;}
const ticks=[...new Set([0,...Array.from({length:4},(_,i)=>Math.round(plan.years*(i+1)/4))])];axes+=ticks.map(year=>`<text x="${x(year)}"y="310"text-anchor="middle">${year}年</text>`).join('');$('growth-chart').innerHTML=`<svg viewBox="0 0 710 325"role="img"aria-label="商品別の資産推移。詳細は年ごとの数値をご覧ください"style="font-size:13px;fill:#667772"><text x="75"y="16">評価額（円）</text>${axes}${paths}<path d="M${rows.map(r => `${x(r.year)},${y(r.principal)}`).join(' L')}"fill="none"stroke="#243f38"stroke-width="2"stroke-dasharray="6 4"/></svg>`;legend([...items,{name:'投資元本（破線）',color:'#243f38'}],'growth-legend');renderPie(result,items);$('annual-data').innerHTML=rows.map(r=>`<tr><td>${r.year}年</td><td>${yen(r.principal)}</td><td>${yen(r.total)}</td><td>${yen(r.total-r.principal)}</td></tr>`).join('');}
function renderPie(result,items){let segments=items.map((item,i)=>({...item,value:$('allocation-basis').value==='monthly'?plan.products[i].monthly:result.final.balances[i]}));if($('allocation-group').value==='category'){segments=categories.map((category,i)=>({name:category,color:color(i),value:segments.reduce((sum,segment,j)=>sum+(plan.products[j].category===category?segment.value:0),0)}));}
const total=segments.reduce((sum,s)=>sum+s.value,0);if(!total)$('pie-chart').innerHTML='<p class="empty-chart">金額が0円のため、構成比はありません。</p>';else{let angle=-Math.PI/2;const slices=segments.filter(s=>s.value>0).map(s=>{const next=angle+s.value/total*Math.PI*2;const title=`<title>${escape(s.name)}：${yen(s.value)}（${(s.value/total*100).toFixed(1)}%）</title>`;const slice=s.value===total?`<circle cx="120"cy="120"r="105"fill="${s.color}">${title}</circle>`:`<path d="M120,120 L${120 + 105 * Math.cos(angle)},${120 + 105 * Math.sin(angle)} A105,105 0 ${next - angle > Math.PI ? 1 : 0},1 ${120 + 105 * Math.cos(next)},${120 + 105 * Math.sin(next)} Z"fill="${s.color}"stroke="white"stroke-width="1.5">${title}</path>`;angle=next;return slice;}).join('');$('pie-chart').innerHTML=`<svg viewBox="0 0 240 240"role="img"aria-label="${$('allocation-basis').selectedOptions[0].textContent}の${$('allocation-group').selectedOptions[0].textContent}構成比。内訳は下の凡例に記載">${slices}</svg>`;}
legend(segments,'pie-legend',true);}
$('plan').addEventListener('submit',event=>event.preventDefault());$('plan').addEventListener('input',()=>update());$('add-product').addEventListener('click',()=>{if(!update()||plan.products.length>=30)return;plan.products.push({name:`商品${plan.products.length+1}`,category:'その他',initial:0,monthly:10000,rate:3});renderProducts();update();$('products').lastElementChild.querySelector('input').focus();});$('products').addEventListener('click',event=>{const button=event.target.closest('[data-remove]');if(!button||$('products').children.length<=1)return;button.closest('.product').remove();[...$('products').children].forEach((row,i)=>{row.querySelector('[data-remove]').dataset.remove=i;});if(update()){renderProducts();update(false);}});for(const id of['allocation-basis','allocation-group'])$(id).addEventListener('change',()=>update(false));renderProducts();update(false);
